package main
import("encoding/json";"flag";"fmt";"io";"os";"github.com/kakon77777-commits/isql-origin-go/conformance";"github.com/kakon77777-commits/isql-origin-go/sidecar";"github.com/kakon77777-commits/isql-origin-go/wire")
func emit(w io.Writer,v any)error{enc:=json.NewEncoder(w);enc.SetEscapeHTML(false);return enc.Encode(v)};func read(path string)([]byte,error){return os.ReadFile(path)}
func run(args []string,out,errw io.Writer)int{if len(args)==0{fmt.Fprintln(errw,"usage: isql-origin-go <decode-omir|decode-orb|mlf-info|conformance>");return 2};switch args[0]{case "decode-omir":if len(args)!=2{fmt.Fprintln(errw,"decode-omir FILE");return 2};b,e:=read(args[1]);if e!=nil{fmt.Fprintln(errw,e);return 2};obj,e:=wire.DecodeOMIR(b);if e!=nil{fmt.Fprintln(errw,e);return 2};tags:=make([]uint64,len(obj.Sections));for i,s:=range obj.Sections{tags[i]=s.Tag};if e:=emit(out,map[string]any{"schema":"isql-origin-go-omir-info/v0.7","format_version":obj.FormatVersion,"object_kind":fmt.Sprintf("%d:%d",obj.ObjectKind.BundleSlot,obj.ObjectKind.LocalID),"profile":fmt.Sprintf("%d:%d",obj.Profile.BundleSlot,obj.Profile.LocalID),"registry_pin_count":len(obj.RegistryPins),"section_tags":tags});e!=nil{return 2};return 0;case "decode-orb":if len(args)!=2{fmt.Fprintln(errw,"decode-orb FILE");return 2};b,e:=read(args[1]);if e!=nil{fmt.Fprintln(errw,e);return 2};orb,e:=wire.DecodeORB(b);if e!=nil{fmt.Fprintln(errw,e);return 2};if e:=emit(out,map[string]any{"schema":"isql-origin-go-orb-info/v0.7","format_version":orb.FormatVersion,"revision":orb.Revision,"entry_count":len(orb.Entries)});e!=nil{return 2};return 0;case "mlf-info":if len(args)!=2{fmt.Fprintln(errw,"mlf-info FILE");return 2};b,e:=read(args[1]);if e!=nil{fmt.Fprintln(errw,e);return 2};info,e:=sidecar.InspectMLF(b);if e!=nil{fmt.Fprintln(errw,e);return 2};if e:=emit(out,info);e!=nil{return 2};return 0;case "conformance":fs:=flag.NewFlagSet("conformance",flag.ContinueOnError);fs.SetOutput(errw);root:=fs.String("root",".","Origin release root");if e:=fs.Parse(args[1:]);e!=nil{return 2};r:=conformance.RunAll(*root);if e:=emit(out,r);e!=nil{return 2};if r.Failures>0{return 1};return 0;default:fmt.Fprintf(errw,"unknown command: %s\n",args[0]);return 2}}
func main(){os.Exit(run(os.Args[1:],os.Stdout,os.Stderr))}
